    float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
    float fbm(vec2 p){ return vn(p)*.55 + vn(p*2.1 + 3.1)*.3 + vn(p*4.3 + 7.7)*.15; }
    void main(){
      float r = length(vL), g = 1. - pow(1. - clamp(vU/.8, 0., 1.), 3.), R = 6.6*(.4 + .6*g);
      float a = uTime*.06*(vLy*2. - 1.), c = cos(a), s = sin(a); vec2 q = mat2(c, -s, s, c)*vL*.32 + vLy*5.3;
      vec2 w = vec2(fbm(q + uTime*.05), fbm(q - uTime*.04 + 4.2));                 // domain warp: billowy, churning
      float n = fbm(q + w*1.4);
      float mask = smoothstep(R, R*.55, r + (n - .5)*2.2);                           // ragged edge
      float dens = smoothstep(.32, .72, n)*mask*smoothstep(.05, .35, vEdge);
      dens *= smoothstep(0., .6, vU)*(1. - smoothstep(6.3, 7.4, vU));
      vec3 base = mix(vec3(.012, .015, .025), vec3(.06, .075, .12), n*n)*(vLy > .5 ? 1.15 : 1.);
